import { createHash, randomBytes } from "node:crypto";

import type {
  AssetRef,

edits.oldText:
function createOpaqueToken(prefix: string, seed: string, secret: string): string {
  const nonce = randomNonce();
  const left = hashString(`${secret}:${prefix}:${seed}:${nonce}`);
  const right = hashString(`${seed}:${secret}:${nonce}:${prefix}`);
  return `${prefix}_${left}${right.slice(0, 12)}`;
}

function randomNonce(): string {
  const values = new Uint32Array(2);
  const cryptoLike = globalThis as unknown as {
    crypto?: { getRandomValues?: (buffer: Uint32Array) => Uint32Array };
  };
  if (cryptoLike.crypto?.getRandomValues) {
    cryptoLike.crypto.getRandomValues(values);
    return `${values[0].toString(16)}${values[1].toString(16)}`;
  }
  return `${Math.random().toString(16).slice(2)}${Date.now().toString(16)}`;
}

edits.newText:
function createOpaqueToken(prefix: string, _seed: string, _secret: string): string {
  return `${prefix}_${randomBytes(24).toString("base64url")}`;
}

function hashOpaqueToken(secret: string, token: string): string {
  return createHash("sha256").update(secret).update(":").update(token).digest("hex");
}

